def link(k):
 t,u=S[k]; return f'<a href="{escape(u,quote=True)}">{escape(t)} ↗</a>'
def table(head,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th scope="col">{escape(x)}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row[:-1])+f'<td>{link(row[-1])}</td></tr>' for row in rows)+'</tbody></table></div>'
nav=[('index.html','Overview'),('decision.html','Decision'),('projection.html','Projections'),('stress.html','Black swan'),('process.html','Process'),('law.html','Tax & law'),('costs.html','Costs'),('flagged.html','Flagged for review')]
def page(fn,title,kicker,description,body):
 links=''.join(f'<a {"aria-current=page" if f==fn else ""} href="{f}">{n}</a>' for f,n in nav)
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Inheritance decision guide</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="topbar"><a class="logo" href="index.html"><span class="mark">N</span><span>INHERITANCE <small>DECISION GUIDE</small></span></a><span class="topnote">PRIVATE BY DESIGN <i></i> RESEARCHED NOV 2026</span></div><nav aria-label="Main navigation">{links}</nav></header><main id="main"><div class="heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{description}</p></div>{body}</main><footer><div><b>Inheritance decision guide</b><p>Public research only. No personal property figures are published in this edition.</p></div><p>Research checked 11 November 2026. Rules may change. Not legal, tax, investment or insurance advice.</p><a href="flagged.html">Review limitations →</a></footer></body></html>'''
 (out/fn).write_text(text,encoding='utf-8')

page('index.html','A clearer path forward','EXECUTIVE BRIEF  /  01','A privacy-first framework for a future trust inheritance and an already-owned home.', '''<section class="hero"><div><span class="pill">THE DECISION</span><h2>Keep your options open.</h2><p>Consider retaining the already-owned San Francisco home while comparing three paths for the inherited Cupertino home: move in, rent it, or sell and reinvest. The preferred financial path cannot be established from verified public evidence alone.</p><a class="button" href="decision.html">Explore the decision <span>↗</span></a></div><div class="hero-side"><span>01 / THE DISTINCTION</span><h3>One future transfer.<br>One existing asset.</h3><p>Do not assume the already-owned property is inherited or receives a new income-tax basis at this future transfer.</p></div></section><div class="section-head"><div><p class="eyebrow">AT A GLANCE</p><h2>What matters most</h2></div><a href="flagged.html">See open questions →</a></div><div class="cards"><article><span class="num">01</span><h3>Property tax</h3><p>The inherited home may be reassessed. A qualifying intergenerational exclusion depends on relationship, use, claims and value limits.</p><a href="law.html">Understand the rules →</a></article><article><span class="num">02</span><h3>Estate & basis</h3><p>Estate tax applies to the estate, not a simple per-beneficiary allowance. A basis adjustment depends on the property and trust.</p><a href="law.html">Review the tax picture →</a></article><article><span class="num">03</span><h3>Real-world risk</h3><p>Inflation, house prices, market returns and insurance can change unevenly. A smooth forecast is not a guarantee.</p><a href="stress.html">Explore stress cases →</a></article></div><div class="notice"><b>Why the numbers are blank</b><p>Rounded personal figures can still identify a household. This public site excludes private inputs and derived outputs. Future values, quotes and tax outcomes are not official facts and are flagged rather than presented as verified.</p><a href="flagged.html">Read all limitations →</a></div>''')
rows=[('Live in the inherited home','Potential property-tax relief if eligible; forego alternative housing use; budget owner costs.','Eligibility, assessed value, relocation effects and lost use of existing home.','boe'),('Rent the inherited home','Rental revenue may offset costs; reassessment and taxable rental income can change returns.','Rent, vacancies, landlord insurance, repairs, management and tax basis.','renttax'),('Sell and reinvest','Releases sale proceeds for a diversified portfolio; selling costs, basis and market risk matter.','Estate inclusion, actual basis, selling costs, taxes and portfolio allocation.','basis'),('Keep the already-owned home','Compare incremental costs and income across all three paths; ownership does not change merely because another home is inherited.','Occupancy, insurance, applicable rent rules and future change-in-ownership events.','sf')]
page('decision.html','Compare the paths','DECISION FRAMEWORK  /  02','A good decision compares after-tax wealth, cash flow, liquidity and housing needs on the same timeline.', '<h2>Three choices, one consistent comparison</h2>'+table(['Path','Potential effect','Critical unknowns','Official context'],rows)+'''<div class="notice"><b>Working direction, not a winner</b><p>Preserving the already-owned home is a reasonable starting point to investigate; it is not automatically optimal. Selling the inherited home could reduce concentrated real-estate exposure, but no winner can be verified without the trust terms, basis, costs and risk preferences.</p></div><h2>Comparison logic</h2><p>For each path, calculate after-tax annual cash flow and ending wealth after a hypothetical sale on the same date. Include owner housing value or replacement housing cost, net rent, tax, insurance, utilities, maintenance, vacancy, sale costs and investment taxes. Avoid counting the same housing or rent benefit twice. Treat all starting values, rates and future outcomes as unverified until privately documented.</p>''')
rows=[]
for y in range(2026,2077): rows.append((str(y),'—','—','—','—','rtc'))
page('projection.html','Year-by-year outlook','MODEL & METHOD  /  03','A 50-year horizon needs explicit assumptions, not false precision. Dashes mean withheld or not independently verified.', '''<div class="notice"><b>No household forecast is published</b><p>Estimates, bills, quotes and personal inputs cannot be corroborated from official public sources without exposing the household. Likewise, future prices, rates and costs are not verifiable facts. They are intentionally blank.</p></div><h2>Projection structure</h2><p>In a private analysis, carry forward each year’s market value using that year’s assumed return, assessed value under the applicable rules, and each expense using its own escalation path. At the transfer date recalculate the assessment using the applicable eligibility and law. Include fixed charges separately from ad valorem tax. Calculate real dollars by dividing nominal amounts by cumulative inflation. None of these formulas verifies future outcomes.</p>'''+table(['Year','Market value','Assessed value','Property tax','Operating costs','Official context'],rows))
rows=[('Inflation shock','1980 US CPI rose 13.5% on an annual-average basis; 2009 fell 0.4%.','Escalate insurance, utilities and repairs separately; compare real and nominal wealth.','cpi'),('Housing downturn','A regional house-price index has moved up and down; an index is not an appraisal.','Apply a decline and an extended recovery; test reassessment and sale timing.','fed'),('Market crash & sequence risk','Diversification does not guarantee against losses.','Test an early portfolio drawdown plus delayed recovery and liquidity needs.','sec'),('Insurance or repair shock','Earthquake, flood and wear are usually excluded from standard homeowners policies.','Stress a major uncovered repair alongside premium or deductible changes.','insurance'),('Solar tariff change','Export credits and net billing depend on the applicable tariff.','Do not equate a bill credit with cash profit; stress lower compensation and charges.','cpuc')]
page('stress.html','When the unexpected happens','RISK & RESILIENCE  /  04','Separate stress tests from the baseline. Historical episodes illustrate variability, not probabilities or predictions.',table(['Shock','Evidence','Decision test','Official context'],rows)+'''<h2>How to use these tests</h2><p>Model shocks jointly as well as individually: for example a property decline together with higher repair costs and a stock market drop. Compare outcomes under different timing, including immediately before and after the transfer. Keep liquidity sufficient for taxes and essential repairs; no numerical reserve is verified here. Do not extrapolate national CPI or regional house indices into a household-specific forecast.</p>''')
rows=[('1','Before the transfer','Review the trust, ownership, beneficiaries, powers, debts, prior gifts and likely estate inclusion with counsel.','trust'),('2','At death','Obtain death certificates, secure the property, notify the trustee and insurer, and document the date and condition.','trust'),('3','Value assets','Commission a date-of-death appraisal and inventory all estate assets and liabilities; assess whether alternate valuation or exceptions apply.','706'),('4','Review basis','Determine the applicable income-tax basis; trust status alone does not guarantee a step-up.','basis'),('5','Notify assessor','File the applicable change-in-ownership documents and ask the county about supplemental assessments and deadlines.','county'),('6','If seeking family-home relief','Check eligibility and occupy and file the homeowners’ or disabled veterans’ exemption within one year to seek relief from transfer date; file the parent-child claim within the applicable period.','boe'),('7','Estate tax filing','Determine whether Form 706 is required or useful for portability. It is generally due nine months after death; a filing extension is available, but does not automatically extend payment.','irs'),('8','Choose and implement','Review net sale proceeds or rental economics, housing needs and portfolio risks; keep records of all decisions and expenditures.','sell'),('9','Cash and retirement accounts','Confirm ownership, named beneficiaries and account type; inherited retirement accounts may have separate distribution requirements.','ira')]
page('process.html','From trust to decision','PRACTICAL ROADMAP  /  05','The exact sequence depends on the trust, title, beneficiaries and the law at the time.',table(['Step','Phase','Action','Official context'],rows)+'''<div class="notice"><b>Keep documents private</b><p>Share trust papers, assessment notices, account records, quotes and appraisals through a secure channel with qualified professionals—not on this public site.</p></div>''')
rows=[('Federal estate tax · 2026','$15,000,000 basic exclusion for 2026 decedents. Filing also depends on gross estate and adjusted taxable gifts; portability may require a return regardless of size.','irs'),('Federal estate tax · 2027','$15,480,000 basic exclusion for 2027 decedents; do not treat it as a per-heir allowance.','irs27'),('Future estate tax · 2040–2050','— Unverified. Future indexed amounts, legislation and household-specific remaining exclusion are unknown.','irs27'),('California estate tax','No California estate tax return is required for deaths on or after January 1, 2005 under current law.','sco'),('Prop 19 value allowance','$1,044,586 for qualifying transfers from February 16, 2025 through February 15, 2027; future amounts are unknown. Exact statutory figure shown.','allow'),('Prop 19 assessment','If eligible, excess fair market value over factored base-year value plus applicable allowance is added to factored base-year value. Relief requires qualifying facts and filing.','boe'),('Existing property assessment','Prop 13 generally limits the annual inflation adjustment to 2%; changes in ownership and new construction may alter value.','rtc'),('Income-tax basis','A basis adjustment often applies to property acquired from a decedent, but IRS Rev. Rul. 2023-2 describes a trust scenario without one.','basis'),('San Francisco rental rules','For covered units the annual allowable increase is 1.6% for March 2026 through February 2027; verify applicability.','sf'),('Legislative watch','SB 974 was approved September 27, 2026 and addresses generational transfers involving special-needs trusts. It is enacted, not merely proposed; relevance is unverified.','bill')]
page('law.html','Tax & law','OFFICIAL RULES  /  06','Current rules are a starting point, not a guarantee of the law at the eventual transfer.',table(['Topic','What the source says','Official source'],rows)+'''<div class="notice"><b>Estate-tax room is unknown</b><p>Do not subtract only a house value from an exclusion: include other includible assets, liabilities and allowable deductions, adjusted taxable gifts, credits and any portability. Filing threshold and actual tax liability are different calculations. Cash-account type may affect income tax; check inherited IRA rules.</p></div>''')
rows=[('Inherited home · insurance','—','No verified property-specific owner or landlord quote. Compare coverage, deductible, replacement cost and exclusions.','insurance'),('Already-owned home · insurance','—','No verified mixed-occupancy or rental quote. Check policy matches actual occupancy and rentals.','insurance'),('Water and electricity','—','Private bills and future tariffs are not verified. Model each property separately.','cpuc'),('Solar credits','—','Determine tariff, fixed charges and annual true-up; bill credits are not necessarily cash proceeds.','cpuc'),('Maintenance and capital repairs','—','No verified reserve or future repair schedule. Test routine maintenance and large irregular capital work separately.','insurance'),('Property taxes and assessments','—','Obtain county assessment, tax rate area, direct charges and any supplemental bills privately.','county'),('Rental cash flow','—','Verify leases, vacancy, coverage, rent rules, expenses and tax deductions.','renttax')]
page('costs.html','The cost of keeping','OPERATING COSTS  /  07','Reliable comparisons need property-specific records and quotes; public averages are not substitutes.',table(['Item','Verified amount','What to check','Official context'],rows)+'''<h2>Planning categories</h2><p>Compare taxes, property and liability insurance, water, electricity, waste, ordinary repairs, major capital replacements, management, vacancy and any debt. Include both properties consistently, and distinguish costs that change with the decision from those that do not.</p>''')
rows=[('Privacy','Previous public Git history and older repository files may contain identifying or linkable property figures. This publication excludes those files; this does not erase the repository, caches or history.','insurance'),('Unverified values','Household values, rents, assessments, utilities, insurance premiums, repairs, cash and trust facts are not independently verified and are omitted.','county'),('Projection gap','No verified 50-year numerical household forecast or best financial outcome can be published without invented assumptions or revealing private inputs.','fed'),('Estate exposure','Remaining exclusion and actual tax cannot be determined without a complete estate inventory, gifts, deductions and trust review.','irs'),('Parent-child qualification','Relationship, residence, trust terms and claim eligibility are not established; the result is not automatic.','boe'),('Future law','Future exclusion amounts, tax rates and laws cannot be confirmed; revisit official sources nearer the event.','law'),('Local expenses','No property-specific official insurance quotes or parcel-specific rate and fixed-charge breakdown were established.','insurance'),('Solar','Tariff, account transfer, bill true-up and surplus compensation require confirmation; credit is not guaranteed profit.','cpuc'),('Prior analysis','Earlier public editions may contain owner-derived figures, overconfident conclusions or unsourced assumptions and should not be relied on as this edition.','irs')]
page('flagged.html','Flagged for review','OPEN ITEMS  /  08','Unverified does not mean false. It means a reliable, privacy-preserving conclusion is not yet available.',table(['Item','Limitation','Official context'],rows)+'''<div class="notice"><b>Important privacy limitation</b><p>Making a new Pages publication does not make a public repository private or remove historic commits. The repository owner should assess repository visibility, history, forks, search indexes and caches with GitHub support. A public site and a public repository cannot guarantee confidentiality.</p></div>''')
